CREATE CLUSTER ingest SIZE 'bench';
CREATE SOURCE ticks_src IN CLUSTER ingest FROM LOAD GENERATOR COUNTER (TICK INTERVAL '100ms') WITH (TIMESTAMP INTERVAL '100ms');
CREATE TABLE ticks FROM SOURCE ticks_src;
CREATE CLUSTER c0 SIZE 'bench';
CREATE CLUSTER c1 SIZE 'bench';
CREATE CLUSTER c2 SIZE 'bench';
CREATE CLUSTER c3 SIZE 'bench';
CREATE MATERIALIZED VIEW mv_0 IN CLUSTER c0 AS SELECT counter, g FROM ticks, generate_series(1, (floor((counter + 1) * 0.1 + 0::numeric / 400) - floor(counter * 0.1 + 0::numeric / 400))::int) AS g;
CREATE MATERIALIZED VIEW mv_1 IN CLUSTER c1 AS SELECT counter, g FROM ticks, generate_series(1, (floor((counter + 1) * 0.1 + 1::numeric / 400) - floor(counter * 0.1 + 1::numeric / 400))::int) AS g;
